        except Exception as e:
            print(f"Error processing {filename}: {e}")
            results.append({
                'filename': filename,
                'date': None,
                'total_amount': None
            })

    # Write to Excel
    wb = Workbook()
    ws = wb.active
    ws.title = "results"

    ws.append(['filename', 'date', 'total_amount'])

    for res in results:
        ws.append([res['filename'], res['date'], res['total_amount']])

    wb.save(output_file)

