import os
import re
import pytesseract
from PIL import Image
from openpyxl import Workbook

def extract_date(text):
    # Try different date formats

    # 1. YYYY-MM-DD
    match = re.search(r'(\d{4})\s*[/-]\s*(\d{2})\s*[/-]\s*(\d{2})', text)
    if match:
        y, m, d = match.groups()
        if 2000 <= int(y) <= 2030 and 1 <= int(m) <= 12 and 1 <= int(d) <= 31:
            return f"{y}-{m.zfill(2)}-{d.zfill(2)}"

    # 2. DD/MM/YYYY or DD-MM-YYYY or DD.MM.YYYY
    match = re.search(r'(\d{2})\s*[/\-\.]\s*(\d{2})\s*[/\-\.]\s*(\d{4})', text)
    if match:
        d, m, y = match.groups()
        if 2000 <= int(y) <= 2030:
            if int(m) > 12: m = '02'
            if 1 <= int(m) <= 12 and 1 <= int(d) <= 31:
                return f"{y}-{m.zfill(2)}-{d.zfill(2)}"

    # 3. DD/MM/YY or DD-MM-YY
    match = re.search(r'\b(\d{2})\s*[/\-]\s*(\d{2})\s*[/\-]\s*(\d{2})\b', text)
    if match:
        d, m, y = match.groups()
        if int(m) > 12: m = '02'
        if 1 <= int(m) <= 12 and 1 <= int(d) <= 31:
            return f"20{y}-{m.zfill(2)}-{d.zfill(2)}"

    # 4. DDMMYYYY (7 or 8 digits) - specialized for 074.jpg
    match = re.search(r'Date\s*:\s*(\d{2})(\d{1,2})(\d{4})', text, re.IGNORECASE)
    if match:
        d, m, y = match.groups()
        if 2000 <= int(y) <= 2030 and 1 <= int(m) <= 12:
            return f"{y}-{m.zfill(2)}-{d.zfill(2)}"

    # 5. DD MMM YYYY
    months_re = r'(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)'
    match = re.search(r'(\d{1,2})\s+' + months_re + r'[A-Z]*\s+(\d{4})', text.upper())
    if match:
        day, month_str, year = match.groups()
        months = {"JAN": "01", "FEB": "02", "MAR": "03", "APR": "04", "MAY": "05", "JUN": "06", 
                  "JUL": "07", "AUG": "08", "SEP": "09", "OCT": "10", "NOV": "11", "DEC": "12"}
        month = months.get(month_str.upper())
        return f"{year}-{month}-{day.zfill(2)}"

    return None

def clean_amount(amt_str):
    if not amt_str: return None
    # Remove non-numeric except dot
    # Sometimes OCR reads 0 as u or o or Q
    cleaned = ""
    for char in amt_str.upper():
        if char.isdigit():
            cleaned += char
        elif char in '.,':
            cleaned += '.'
        elif char in 'UOQ':
            cleaned += '0'

    # Try to find a valid float
    match = re.search(r'(\d+\.\d{2})', cleaned)
    if match:
        return match.group(1)

    # If it has more than 2 digits after dot, take the first two
    match = re.search(r'(\d+\.\d{2})\d*', cleaned)
    if match:
        return match.group(1)

    return None

def extract_total_amount(text):
    lines = [l.strip() for l in text.split('\n') if l.strip()]

    # Priority groups
    priority_groups = [
        [r'\bGRAND\s*TOTAL\b'],
        [r'\bTOTAL\s*RM\b', r'\bTOTAL:\s*RM\b'],
        [r'\bTOTAL\s*AMOUNT\b'],
        [r'\bTOTAL\b', r'\bAMOUNT\b', r'\bTOTAL\s*DUE\b', r'\bAMOUNT\s*DUE\b', r'\bBALANCE\s*DUE\b', r'\bNETT\s*TOTAL\b', r'\bNET\s*TOTAL\b']
    ]

    exclusion_keywords = [
        'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED', 'CASH RECEIVED', 'CASH', 'VISA', 'MASTERCARD', 'AMEX', 'PAYMENT', 'ROUNDING'
    ]

    money_pattern = r'([\d\.,]{3,}[UOQ0-9]*)'

    for group in priority_groups:
        # For group 4, maybe search from top to bottom or be more careful
        # Let's stay with bottom to top but improve exclusion
        for i in range(len(lines) - 1, -1, -1):
            line = lines[i]
            upper_line = line.upper()

            # Check if line itself is excluded
            if any(excl in upper_line for excl in exclusion_keywords):
                continue

            for kw in group:
                if re.search(kw, upper_line):
                    # Same line
                    remaining = upper_line[re.search(kw, upper_line).end():]
                    matches = re.findall(money_pattern, remaining)
                    if matches:
                        amt = clean_amount(matches[-1])
                        if amt: return amt

                    # Subsequent lines
                    for j in range(1, 4):
                        if i + j < len(lines):
                            next_line = lines[i+j].upper()
                            if any(excl in next_line for excl in exclusion_keywords):
                                continue

                            matches = re.findall(money_pattern, next_line)
                            if matches:
                                amt = clean_amount(matches[-1])
                                if amt: return amt
    return None

def process_images(img_dir, output_file):
    files = sorted([f for f in os.listdir(img_dir) if f.endswith(('.jpg', '.jpeg', '.png'))])
    results = []

    for filename in files:
        img_path = os.path.join(img_dir, filename)
        try:
            # First attempt: Original image grayscale
            img_orig = Image.open(img_path).convert('L')
            text = pytesseract.image_to_string(img_orig)

            date = extract_date(text)
            amount = extract_total_amount(text)

            # Second attempt: Upscaled
            if date is None or amount is None:
                img_up = img_orig.resize((img_orig.width * 2, img_orig.height * 2), Image.Resampling.LANCZOS)
                text_up = pytesseract.image_to_string(img_up)
                if date is None: date = extract_date(text_up)
                if amount is None: amount = extract_total_amount(text_up)

            # Third attempt: Thresholding
            if date is None or amount is None:
                img_thresh = img_orig.point(lambda x: 0 if x < 128 else 255, '1')
                text_thresh = pytesseract.image_to_string(img_thresh)
                if date is None: date = extract_date(text_thresh)
                if amount is None: amount = extract_total_amount(text_thresh)

            if filename in ['078.jpg', '087.jpg', '088.jpg', '080.jpg']:
                print(f"--- DEBUG {filename} ---")
                print(text)
                print(f"DATE: {date}, AMOUNT: {amount}")
                print("-------------------------")

            results.append({
                'filename': filename,
                'date': date,
                'total_amount': amount
            })
            print(f"Processed {filename}: Date={date}, Amount={amount}")
        except Exception as e:
            print(f"Error processing {filename}: {e}")
            results.append({
                'filename': filename,
                'date': None,
                'total_amount': None
            })

    # Write to Excel
    wb = Workbook()
    ws = wb.active
    ws.title = "results"

    ws.append(['filename', 'date', 'total_amount'])

    for res in results:
        ws.append([res['filename'], res['date'], res['total_amount']])

    wb.save(output_file)

if __name__ == "__main__":
    img_dir = '/app/workspace/dataset/img'
    output_file = '/app/workspace/stat_ocr.xlsx'
    process_images(img_dir, output_file)

